args.command:
ls -la && python3 - <<'PY'
import os
for root, dirs, files in os.walk('.'):
    dirs[:] = [d for d in dirs if d not in {'.git','vendor'}]
    for f in files:
        if f == 'go.mod': print(os.path.join(root,f))
PY

