perl -MFile::Find - <<'PL'
use strict; use warnings;
my @files; find({wanted=>sub { return if $File::Find::dir =~ m{(?:^|/)\.git(?:/|$)}; push @files,$File::Find::name if /\.go\z/ && -f }, no_chdir=>1}, '.');
my (%F,%meta,@decls);
sub mask {
 my $s=shift;
 $s =~ s{"(?:\\.|[^"\\])*"}{' ' x length($&)}gse;
 $s =~ s{`[^`]*`}{my $x=$&; $x=~s/[^\n]/ /g; $x}gse;
 $s =~ s{//[^\n]*}{' ' x length($&)}gse;
 $s =~ s{/\*.*?\*/}{my $x=$&; $x=~s/[^\n]/ /g; $x}gse;
 return $s;
}
for my $f (@files) { open my $h,'<',$f or die $!; local $/; my $raw=<$h>; my $s=mask($raw); my ($pkg)=$s=~/\bpackage\s+(\w+)/; next unless $pkg; (my $dir=$f)=~s{/[^/]+$}{}; $dir=~s{^\./}{}; my $path='github.com/usememos/memos'.($dir eq '.'?'':"/$dir"); my %imp;
 while ($raw =~ /^\s*import\s*(?:\((.*?)\)|([^\n]+))/msg) { my $s=$1//$2; while ($s =~ /^\s*(?:(\w+|\.|_)\s+)?"([^"]+)"/mg) { my($a,$p)=($1,$2); next if defined($a) && ($a eq '.'||$a eq '_'); $a //= ($p=~m{([^/]+)$})[0]; $imp{$a}=$p; } }
 $meta{$f}={raw=>$raw,s=>$s,pkg=>$pkg,path=>$path,imp=>\%imp};
 while ($s =~ /\bfunc\s*(?:\(\s*([^)]+?)\s*\)\s*)?([A-Za-z_]\w*)\s*(?:\[[^\]]*\]\s*)?\(/g) {
   my($recv,$name,$pos)=($1,$2,$-[2]); my $line=1+(substr($raw,0,$pos)=~tr/\n//); my $kind=defined($recv)?'method':'func'; my $rt=''; if(defined $recv){ $rt=$recv; $rt=~s/^\s*\w+\s+//; $rt=~s/[\s*\[\]]//g; $rt=~s/.*\.//; }
   my $key=defined($recv)?"$path.($rt).$name":"$path.$name";
   my $d={key=>$key,path=>$path,pkg=>$pkg,name=>$name,recv=>$rt,kind=>$kind,file=>$f,line=>$line,pos=>$pos}; push @decls,$d; $F{$key}=$d;
 }
}
my (%sites,%callers,%methodRaw);
for my $f (@files) { next unless $meta{$f}; my $m=$meta{$f}; my $s=$m->{s};
 # calling function approximation by nearest preceding declaration (sufficient for distinct caller estimate)
 my @local=sort {$a->{pos}<=>$b->{pos}} grep {$_->{file} eq $f} @decls;
 sub caller_at { my($p)=@_; my $c='<package-init>'; for(@local){last if $_->{pos}>$p;$c=$_-> {key}} return "$f::$c" }
 while ($s =~ /\b([A-Za-z_]\w*)\s*\.\s*([A-Za-z_]\w*)\s*\(/g) { my($a,$n,$p)=($1,$2,$-[0]); if(my $ip=$m->{imp}{$a}) {my $k="$ip.$n"; if($F{$k}){$sites{$k}++;$callers{$k}{caller_at($p)}=1}} $methodRaw{$n}++; }
 while ($s =~ /(?<![\.\w])([A-Za-z_]\w*)\s*\(/g) { my($n,$p)=($1,$-[1]); my $k="$m->{path}.$n"; next unless $F{$k}; next if $p==$F{$k}{pos}; $sites{$k}++;$callers{$k}{caller_at($p)}=1; }
}
my @rank=sort {($sites{$b->{key}}//0)<=>($sites{$a->{key}}//0)} grep {$_->{path}=~m{/internal(?:/|$)} && $_->{kind} eq 'func'} @decls;
print "FILES ".scalar(@files)." DECLS_INTERNAL ".scalar(grep {$_->{path}=~m{/internal(?:/|$)}} @decls)."\n";
for my $d (@rank[0..($#rank<29?$#rank:29)]) { my $k=$d->{key}; print join("\t",$sites{$k}//0,scalar(keys %{$callers{$k}//{}}),$d->{file}.':'.$d->{line},$k),"\n"; }
print "METHODS_RAW_SELECTORS\n"; my @mr=sort{$methodRaw{$b}<=>$methodRaw{$a}} keys %methodRaw; print join("\n",map{"$methodRaw{$_}\t$_"}@mr[0..($#mr<29?$#mr:29)]),"\n";
PL

